import{_ as e,c as s,a as i,o as a}from"./app-CZUMMfB5.js";const l={};function t(r,n){return a(),s("div",null,n[0]||(n[0]=[i(`<h3 id="_14所总体部103室" tabindex="-1"><a class="header-anchor" href="#_14所总体部103室"><span>14所总体部103室</span></a></h3><p>论文或项目的介绍要从以下方面出发：这么做的意义，为什么要做这个工作（比如为什么会选择这个研究方向），解决了什么问题，和现在有的工作相比的优势和特点，要突出工作的一个重点，不需要把侧重点关注在使用了什么方法，完成了什么内容上。注重逻辑表达和整体的叙述，了解军工相关的背景，培养相关的军工情怀</p><h3 id="联通数科实习生" tabindex="-1"><a class="header-anchor" href="#联通数科实习生"><span>联通数科实习生</span></a></h3><p>如何解决项目中的高并发难题？</p><p>docker部署项目的流程</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">[本地项目代码]</span>
<span class="line">     │</span>
<span class="line">     ├──➤ 编写 Dockerfile</span>
<span class="line">     │</span>
<span class="line">     ├──➤ 构建镜像：docker build</span>
<span class="line">     │</span>
<span class="line">     ├──➤ 运行容器：docker run / docker compose</span>
<span class="line">     │</span>
<span class="line">     └──➤ 测试访问 &amp; 持久化配置（端口、卷、网络）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常用的git命令</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line"># 克隆并开发</span>
<span class="line">git clone &lt;repo-url&gt;</span>
<span class="line">cd repo</span>
<span class="line">git checkout -b feature/login</span>
<span class="line"># ...开发</span>
<span class="line">git add .</span>
<span class="line">git commit -m &quot;添加登录功能&quot;</span>
<span class="line">git push origin feature/login</span>
<span class="line"></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>springboot自动装配的流程：自动装配的本质是：Spring Boot 根据类路径下的依赖和配置，自动将 Bean 注册到 Spring 容器中。例如，当你引入 spring-boot-starter-web 依赖时，Spring Boot 会自动配置嵌入式 Tomcat 服务器、Spring MVC 等。</p><p>@SpringBootApplication是启动类上的核心注解，它组合了三个注解： @SpringBootConfiguration：等同于 @Configuration，声明当前类是配置类。 @EnableAutoConfiguration：启用自动装配机制。 @ComponentScan：扫描 @Component、@Service 等组件。</p>`,10)]))}const p=e(l,[["render",t]]),c=JSON.parse('{"path":"/blogs/mianjing/1.html","title":"面试总结","lang":"en-US","frontmatter":{"title":"面试总结","date":"2025/6/28","tags":["面试总结"]},"headers":[{"level":3,"title":"14所总体部103室","slug":"_14所总体部103室","link":"#_14所总体部103室","children":[]},{"level":3,"title":"联通数科实习生","slug":"联通数科实习生","link":"#联通数科实习生","children":[]}],"git":{"createdTime":1752592372000,"updatedTime":1752592372000,"contributors":[{"name":"zxy","email":"431559981@qq.com","commits":1}]},"filePathRelative":"blogs/mianjing/1.md"}');export{p as comp,c as data};
